## Complete Configuration

```yaml
# application.yml
spring:
  data:
    redis:
      host: ${REDIS_HOST:localhost}
      port: 6379
      password: ${REDIS_PASSWORD:}
      database: 0  # Redis database index (0-15)
      connect-timeout: 2000ms
      timeout: 1000ms  # command timeout
      lettuce:
        pool:
          enabled: true
          max-active: 8
          max-idle: 8
          min-idle: 2
          max-wait: 2000ms
```

```xml
<!-- pom.xml -->
<dependency>
    <groupId>org.springframework.boot</groupId>
    <artifactId>spring-boot-starter-data-redis</artifactId>
</dependency>
<!-- For connection pooling -->
<dependency>
    <groupId>org.apache.commons</groupId>
    <artifactId>commons-pool2</artifactId>
</dependency>
```

## RedisTemplate Configuration

```java
@Configuration
public class RedisConfig {

    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory factory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(factory);

        // Keys as plain Strings — readable in Redis CLI
        StringRedisSerializer stringSerializer = new StringRedisSerializer();
        template.setKeySerializer(stringSerializer);
        template.setHashKeySerializer(stringSerializer);

        // Values as JSON — human-readable, handles polymorphism
        GenericJackson2JsonRedisSerializer jsonSerializer =
            new GenericJackson2JsonRedisSerializer();
        template.setValueSerializer(jsonSerializer);
        template.setHashValueSerializer(jsonSerializer);

        template.afterPropertiesSet();
        return template;
    }

    // Convenience template for String-only operations
    @Bean
    public StringRedisTemplate stringRedisTemplate(RedisConnectionFactory factory) {
        return new StringRedisTemplate(factory);
    }
}
```

## Redis Sentinel (High Availability)

```yaml
spring:
  data:
    redis:
      sentinel:
        master: mymaster
        nodes:
          - sentinel1:26379
          - sentinel2:26379
          - sentinel3:26379
        password: ${SENTINEL_PASSWORD:}
```

## Redis Cluster

```yaml
spring:
  data:
    redis:
      cluster:
        nodes:
          - redis-node1:6379
          - redis-node2:6379
          - redis-node3:6379
        max-redirects: 3
```

## Bound Key Operations

```java
// BoundValueOperations: bind a key, operate on it directly
BoundValueOperations<String, Object> userOps =
    redisTemplate.boundValueOps("user:" + userId);

userOps.set(userDTO, Duration.ofMinutes(30));
UserDTO user = (UserDTO) userOps.get();
userOps.expire(Duration.ofMinutes(60));  // extend TTL
```

## Pipelining — Batch Operations

```java
// Load 1000 products into Redis in one round-trip
@Service
public class ProductCacheLoader {
    @Autowired RedisTemplate<String, Object> redis;

    public void bulkLoadProducts(List<Product> products) {
        redis.executePipelined((RedisCallback<Object>) connection -> {
            for (Product p : products) {
                String key = "product:" + p.getId();
                byte[] keyBytes = key.getBytes();
                byte[] valueBytes = serialize(p);  // JSON bytes
                connection.setEx(keyBytes, 600, valueBytes);  // 10 min TTL
            }
            return null;  // ignored — results collected by executePipelined
        });
        // All 1000 SET commands sent in one network round-trip
    }
}

// Read multiple keys at once
public List<Object> getMultiple(List<String> keys) {
    return redis.executePipelined((RedisCallback<Object>) connection -> {
        for (String key : keys) {
            connection.get(key.getBytes());
        }
        return null;
    });
    // Returns List<Object> — one result per command
}
```

## Lua Script — Atomic Operations

```java
// Atomic increment with cap — for rate limiting
private static final RedisScript<Long> INCREMENT_WITH_CAP = RedisScript.of(
    "local current = redis.call('incr', KEYS[1])\n" +
    "if current == 1 then\n" +
    "  redis.call('expire', KEYS[1], ARGV[1])\n" +
    "end\n" +
    "return current",
    Long.class
);

public Long incrementWithExpiry(String key, long ttlSeconds) {
    return redis.execute(INCREMENT_WITH_CAP,
        List.of(key),
        String.valueOf(ttlSeconds));
}

// Usage for rate limiting
public boolean isRateLimited(String userId) {
    String key = "ratelimit:" + userId + ":" + LocalDateTime.now().getHour();
    Long count = incrementWithExpiry(key, 3600);  // expire in 1 hour
    return count > 100;  // limit: 100 requests/hour
}
```

## SessionCallback for Transactions

```java
// MULTI/EXEC — execute multiple commands atomically
public void transferPoints(String fromUser, String toUser, long points) {
    redis.execute(new SessionCallback<Object>() {
        @Override
        public Object execute(RedisOperations operations) {
            operations.watch(List.of("points:" + fromUser));
            Long balance = (Long) operations.opsForValue().get("points:" + fromUser);
            if (balance == null || balance < points) throw new InsufficientPointsException();

            operations.multi();  // START transaction
            operations.opsForValue().decrement("points:" + fromUser, points);
            operations.opsForValue().increment("points:" + toUser, points);
            return operations.exec();  // EXEC — atomic commit
            // If WATCH key changed since watch(), exec() returns null (transaction aborted)
        }
    });
}
```

## Spring Pub/Sub Configuration

```java
// Message listener
@Component
public class CacheInvalidationListener implements MessageListener {
    @Autowired RedisTemplate<String, Object> redis;
    private static final Logger log = LoggerFactory.getLogger(CacheInvalidationListener.class);

    @Override
    public void onMessage(Message message, byte[] pattern) {
        String channel = new String(message.getChannel());
        String body    = new String(message.getBody());
        log.info("Cache invalidation: channel={}, key={}", channel, body);

        // Invalidate local cache entry
        redis.delete(body);  // body contains the cache key to invalidate
    }
}

// Configuration: wire up listener container
@Configuration
public class RedisPubSubConfig {
    @Bean
    public RedisMessageListenerContainer listenerContainer(
            RedisConnectionFactory factory,
            CacheInvalidationListener listener) {

        RedisMessageListenerContainer container = new RedisMessageListenerContainer();
        container.setConnectionFactory(factory);
        container.addMessageListener(
            listener,
            new PatternTopic("cache-invalidate:*")  // wildcard subscribe
        );
        return container;
    }
}

// Publisher service
@Service
public class CacheInvalidationPublisher {
    @Autowired RedisTemplate<String, Object> redis;

    public void invalidateAcrossCluster(String cacheKey) {
        redis.convertAndSend("cache-invalidate:" + cacheKey, cacheKey);
        // All instances listening on 'cache-invalidate:*' receive this
    }
}
```

## Redis Streams — Reliable Messaging

```java
// Producer: append to stream
public void publishOrderEvent(Order order) {
    redis.opsForStream().add(
        StreamRecords.newRecord()
            .in("orders:events")
            .ofMap(Map.of(
                "orderId", order.getId().toString(),
                "status", order.getStatus(),
                "amount", order.getAmount().toString()
            ))
    );
}

// Consumer: read from stream with consumer group (reliable delivery)
@Scheduled(fixedDelay = 100)
public void consumeOrderEvents() {
    List<MapRecord<String, Object, Object>> records = redis.opsForStream().read(
        Consumer.from("order-processors", "instance-1"),
        StreamReadOptions.empty().count(10).block(Duration.ofSeconds(1)),
        StreamOffset.create("orders:events", ReadOffset.lastConsumed())
    );

    for (MapRecord<String, Object, Object> record : records) {
        processOrderEvent(record.getValue());
        redis.opsForStream().acknowledge("orders:events", "order-processors", record.getId());
        // ACK removes from pending list — message won't be redelivered
    }
}
```

## Redis Memory Configuration

```bash
# redis.conf
maxmemory 2gb
maxmemory-policy allkeys-lru  # best for pure cache

# Or allkeys-lfu for skewed access patterns
# maxmemory-policy allkeys-lfu

# For mixed cache + session store:
# maxmemory-policy volatile-lru  # only evicts keys with TTL
```

## Eviction Policy Guide

| Policy | Evicts | Best For |
|--------|--------|----------|
| allkeys-lru | Any key, least recently used | Pure cache |
| allkeys-lfu | Any key, least frequently used | Cache with hot keys |
| volatile-lru | Keys with TTL, least recently used | Mixed cache/session |
| volatile-ttl | Keys with TTL, soonest expiring | Priority-based |
| noeviction | Reject writes when full | Session store (never drop) |

## Memory-Efficient Key Design

```java
// Short keys save memory — especially for millions of keys
// BAD: "user:session:data:" + userId  (long prefix)
// GOOD: "us:" + userId

// Redis automatic compact encoding for small structures
// Hash with < 128 fields and small values → ziplist/listpack (compact)
// Hash with >= 128 fields → hashtable (full size)
// Configure thresholds:
// hash-max-listpack-entries 128
// hash-max-listpack-value 64
```

## SCAN Instead of KEYS

```java
// NEVER: redis.keys("product:*")  — blocks server!

// GOOD: SCAN iterates in batches of ~100 without blocking
public void invalidateProductCache(String pattern) {
    ScanOptions options = ScanOptions.scanOptions()
        .match("product:*")
        .count(100)  // batch size hint
        .build();

    try (Cursor<byte[]> cursor = redisTemplate.scan(options)) {
        List<String> keysToDelete = new ArrayList<>();
        cursor.forEachRemaining(key -> keysToDelete.add(new String(key)));
        if (!keysToDelete.isEmpty()) {
            redisTemplate.delete(keysToDelete);
        }
    }
}
```

## Monitor Memory Usage

```bash
# Redis CLI memory stats
redis-cli INFO memory
# used_memory: actual data memory
# used_memory_rss: OS-allocated memory (includes fragmentation)
# mem_fragmentation_ratio: > 1.5 = high fragmentation

# Per-key memory
redis-cli DEBUG OBJECT product:12345
# serializedlength, encoding, qlength

# Find big keys
redis-cli --bigkeys
# Scans and reports largest keys per type
```
